/**
 * Equipment Inventory (file 6914) — mock data
 * Generated by VistA Service Enablement Workbench from:
 *   - Live ^ENG(6914,*) samples (VADEMO, 2026-09-28, IEN 443–454)
 *   - DD survey: VISTA.EQUIPMENTINV6914.cls field manifest
 *   - File 49 SERVICE/SECTION lookup (VADEMO)
 *   - Enum DISPLAYLIST values from capability graph nodes
 *
 * Pointer fields use display-name strings; the REST backend resolves to IEN via
 * FileMan lookup (DIC lookup by .01 value).
 */

// ── Screen 1: Equipment Identity & Acquisition ──────────────────────────────

export interface EquipmentIdentity {
  /** fld .01 — allocated by server (next-IEN from ^ENG(6914,0)^3+1) */
  entryNumber?: number;
  /** fld 1  → 6912 MANUFACTURER LIST FILE */
  manufacturer: string;
  /** fld 3  free text, often manufacturer's own product name */
  mfgrEquipmentName: string;
  /** fld 4  model number / designation */
  model: string;
  /** fld 5  serial number — must be unique (FC xref duplicate check) */
  serial: string;
  /** fld 6  → 6911 EQUIPMENT CATEGORY */
  equipmentCategory: string;
  /** fld 18 → 6917 CATEGORY STOCK NUMBER */
  categoryStockNumber: string;
  /** fld 7  SET: NX | BS | ADP | VM | NX-R | BS-R */
  typeOfEntry: 'NX' | 'BS' | 'ADP' | 'VM' | 'NX-R' | 'BS-R' | '';
  /** fld 20.1 SET: CONSTRUCTED | GIFT/BEQUEST/DONATION | GOVERNMENT FURNISHED | LEASE | PURCHASE | OTHER */
  acquisitionMethod: string;
  /** fld 13 FileMan date (YYYMMDD internal → display as MM/DD/YYYY) */
  acquisitionDate: string;
  /** fld 10 → 440 VENDOR */
  vendorPointer: string;
  /** fld 31.5 dollars */
  originalAssetValue: number;
  /** fld 14 FileMan date */
  warrantyExpDate: string;
  /** fld 51 → 6914 self-reference IEN of item being replaced */
  replacingEntryNumber: number | null;
}

// ── Screen 2: Ownership & Location ──────────────────────────────────────────

export interface EquipmentOwnership {
  /** fld 21 → 49 SERVICE/SECTION */
  servicePointer: string;
  /** fld 20 SET: IN USE | OUT OF SERVICE | LOANED OUT | TURNED IN | DISPOSAL | PENDING DISPOSAL | OTHER */
  useStatus: string;
  /** fld 2  → 6914 self-reference IEN of parent system */
  parentSystem: number | null;
  /** fld 24 → 6928 ENG SPACE (room/location) */
  location: string;
  /** fld 9  SET: YES | NO */
  lockoutRequired: 'YES' | 'NO';
  /** fld 53 SET: LIKE NEW | GOOD | POOR */
  conditionCode: 'LIKE NEW' | 'GOOD' | 'POOR' | '';
  /** fld 60 3–5 char VA station number */
  stationNumber: string;
  /** fld 25 9–10 char VA property management number */
  vaPmNumber: string;
  /** fld 19.5 SET: YES | NO */
  serviceContract: 'YES' | 'NO';
  /** fld 19.6 numeric; only relevant when serviceContract = YES */
  serviceContractCost: number;
  /** fld 26 3–15 char local identifier */
  localIdentifier: string;
  /** fld 23 FileMan date — last physical count */
  physicalInventoryDate: string;
  /** fld 27 SET: YES | NO — Joint Commission / JCAHO equipment */
  jcaho: 'YES' | 'NO';
}

// ── Screen 3: Financial ──────────────────────────────────────────────────────

export interface EquipmentFinancial {
  /** fld 33 SET: YES | NO */
  controlledItem: 'YES' | 'NO';
  /** fld 34 SET: CAPITALIZED/ACCOUNTABLE | NOT CAPITALIZED/ACCOUNTABLE | SENSITIVE/NON-ACCOUNTABLE
   *  gates RULE.FinancialEligibility (FA doc to Austin) */
  investmentCategory: string;
  /** fld 35 3–30 char fund control point */
  fundControlPoint: string;
  /** fld 62 → NXFUND (6946) */
  fund: string;
  /** fld 61 → NXBOC (6944) budget object code */
  budgetObjectCode: string;
  /** fld 38 → NXSGL (6943) standard general ledger account */
  standardGeneralLedger: string;
  /** fld 64 SET: MEDICAL | NON-MEDICAL | DONATED */
  equityAccount: 'MEDICAL' | 'NON-MEDICAL' | 'DONATED' | '';
  /** fld 37 → 4202 BUDGET OBJECT CODE (A/O) */
  subaccount: string;
}

// ── Composite ─────────────────────────────────────────────────────────────

export type EquipmentData = EquipmentIdentity & EquipmentOwnership & EquipmentFinancial;

// ── Open-question inputs (resolved via Decide stage) ────────────────────────

export interface EquipmentRequest extends EquipmentData {
  /** OQ.WorkOrderPolicy — resolved: Required input.
   *  Pass true to trigger IIWO^ENWONEW3 → file 6920 work order. */
  createInspectionWorkOrder: boolean;
}

