// ── MockDataService ──────────────────────────────────────────────────────────

export class MockDataService {
  /** Returns one mock record (cycles through the pool) */
  private index = 0;

  getMockEquipment(): EquipmentData {
    const rec = MOCK_RECORDS[this.index % MOCK_RECORDS.length];
    this.index++;
    return { ...rec };
  }

  /** Returns all sample records */
  getAllSamples(): EquipmentData[] {
    return MOCK_RECORDS.map(r => ({ ...r }));
  }

  /**
   * Returns a new-entry skeleton with only the fields an operator would
   * typically fill in on screen 1 — the rest left blank for the form.
   */
  getBlankEntry(): Partial<EquipmentData> {
    return {
      typeOfEntry: 'NX',
      useStatus: 'IN USE',
      lockoutRequired: 'NO',
      jcaho: 'NO',
      serviceContract: 'NO',
      serviceContractCost: 0,
      controlledItem: 'NO',
      investmentCategory: 'NOT CAPITALIZED/ACCOUNTABLE',
      equityAccount: 'MEDICAL',
      stationNumber: '500',
      replacingEntryNumber: null,
      parentSystem: null,
    };
  }
}

