// ── Screen layout — derived from the capability graph's formScreens[] ────────
// The model stays FLAT (one EquipmentData object bound across all wizard steps,
// matching Angular two-way binding). Layout is single-sourced HERE, not in the
// data. Each wizard page binds to the slice named below.

export interface ScreenDef {
  screen: number;
  title: string;
  fields: (keyof EquipmentData)[];
}

export const SCREEN_LAYOUT: ScreenDef[] = [
  { screen: 1, title: 'Equipment Identity & Acquisition',
    fields: ['entryNumber','manufacturer','mfgrEquipmentName','model','serial',
             'equipmentCategory','categoryStockNumber','typeOfEntry',
             'acquisitionMethod','acquisitionDate','vendorPointer',
             'originalAssetValue','warrantyExpDate','replacingEntryNumber'] },
  { screen: 2, title: 'Ownership & Location',
    fields: ['servicePointer','useStatus','parentSystem','location',
             'lockoutRequired','conditionCode','stationNumber','vaPmNumber',
             'serviceContract','serviceContractCost','localIdentifier',
             'physicalInventoryDate','jcaho'] },
  { screen: 3, title: 'Financial',
    fields: ['controlledItem','investmentCategory','fundControlPoint',
             'fund','budgetObjectCode','standardGeneralLedger',
             'equityAccount','subaccount'] },
];

/** A page's title plus its field values sliced from a flat record. */
export interface PagedScreen {
  screen: number;
  title: string;
  values: { field: keyof EquipmentData; value: unknown }[];
}

/**
 * Slots a flat EquipmentData record into per-screen groups, in the same order
 * and titles the legacy ScreenMan screens used. Drives the wizard's confirmation
 * page (read-only review) and page-by-page preview. The record itself stays flat.
 */
export function recordByScreen(rec: Partial<EquipmentData>): PagedScreen[] {
  return SCREEN_LAYOUT.map(s => ({
    screen: s.screen,
    title: s.title,
    values: s.fields.map(f => ({ field: f, value: rec[f] })),
  }));
}

/**
 * Coverage check for the mock generator: returns any screen field that has no
 * value in the record. Empty array = every page is fully populated.
 */
export function missingByScreen(rec: Partial<EquipmentData>): { screen: number; field: keyof EquipmentData }[] {
  const gaps: { screen: number; field: keyof EquipmentData }[] = [];
  for (const s of SCREEN_LAYOUT)
    for (const f of s.fields)
      if (rec[f] === undefined || rec[f] === '' || rec[f] === null)
        gaps.push({ screen: s.screen, field: f });
  return gaps;
}
